def mean_median_mad(numbers: List[float]) -> float:
    """ Return Mean, Median and Mean Absolute Deviation (MAD) of input
    numbers.
    >>> mean_median_mad([1.0, 2.0, 3.0, 4.0])
    (2.5, 2.5, 1.0)
    """
    average = sum(numbers) / len(numbers)
    middle_index = int(len(numbers) / 2)
    if len(numbers) % 2 == 1:
        median = sorted(numbers)[middle_index]
    else:
        median = (sorted(numbers)[middle_index] + sorted(numbers)[middle_index - 1]) / 2
    return average, median, mean_absolute_deviation(numbers)


