def _recursive_parse(paren_string: str, start: int, level: int) -> int:
    """Helper method to recursively parse each group of parentheses and return the highest level.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> _recursive_parse('(()()) ((())) () ((())()())', 0, 0)
    2
    """
    is_left = paren_string[start] == '('
    if is_left:
        if len(paren_string) <= start + 1:
            return level
        while paren_string[start + 1] == '(':
            end = _recursive_parse(paren_string, start + 1, level + 1)
            start = end + 1
        return level
    elif paren_string[start] == ')':
        return level
    else:
        raise Exception('Invalid paren_string')

