def check_balanced(paren_string: str) -> bool:
    """ Given a string containing balanced parentheses, your task is to validate whether they are all balanced or not.
    You need to return True if the parentheses are balanced, otherwise False.
    >>> check_balanced('( ) (( )) (( )( ))')
    True
    """
    parentheses = separate_paren_groups(paren_string)
    for parenthesis in parentheses:
        if parenthesis.count('(') != parenthesis.count(')'):
            return False
    return True

    out = []
    stack = []
    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                out.append(stack.pop())
            else:
                # if you see closing parens that there is no closing open parens
                out.append('()')
    while stack:
        # you have open parens that are not closed
        out.append(stack.pop())
    return out


