    """ For a given list of input numbers, calculate the Mean Squared Error around
    the mean of this dataset:
    MSE = average (x - x_mean)^2
    >>> mean_squared_error([1.0, 2.0, 3.0, 4.0])
    1.0
    """
    total = 0
    for number in numbers:
        total += number
    mean = total / len(numbers)
    avg_diff = 0
    for number in numbers:
        avg_diff += (number - mean) ** 2
    return avg_diff / len(numbers)

